    static final class DamageablePlayer extends FakePlayer{DamageablePlayer(ServerLevel l,GameProfile p){super(l,p);}@Override public boolean hurt(net.minecraft.world.damagesource.DamageSource source,float amount){setHealth(getHealth()-amount);return true;}}
    int checks;
    void check(boolean ok,String text){if(!ok)throw new AssertionError(text);checks++;System.out.println("PORTABLE CHECK: "+text);}
    static void field(Object object,String key,Object value)throws Exception{var f=object.getClass().getDeclaredField(key);f.setAccessible(true);f.set(object,value);}
    static void running(boolean value)throws Exception{var f=WaveManager.class.getDeclaredField("gameRunning");f.setAccessible(true);f.setBoolean(null,value);}
