        var wide=boss(l,"abomination",-12,0);player.setPos(.5,80,.9);field(wide.encounter,"hook",new net.minecraft.world.phys.Vec3(-1,player.getBoundingBox().getCenter().y,0));field(wide.encounter,"aim",new net.minecraft.world.phys.Vec3(1,0,0));wide.encounter.tick(l);var hookedField=EncounterAbilities.class.getDeclaredField("hooked");hookedField.setAccessible(true);check(player.getUUID().equals(hookedField.get(wide.encounter)),"Thicker hook captures a player offset by 0.9 blocks");wide.discard();
        verifyGeistIntegration(l,player);
